UPDATE t_message
SET read = #{readFlag},
    read_time = now()
WHERE message_id = #{messageId}
  AND receiver_user_type = #{receiverUserType}
  AND receiver_user_id = #{receiverUserId}
  AND read != #{readFlag}

mapper.select:
SELECT * FROM t_message


        AND receiver_user_type = #{query.receiverUserType}


        AND receiver_user_id = #{query.receiverUserId}


        AND message_type = #{query.messageType}


        AND ( title ILIKE CONCAT('%', #{query.searchWord}, '%')
        OR content ILIKE CONCAT('%', #{query.searchWord}, '%')
        )


        AND read = #{query.readFlag}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') >= TO_CHAR(#{query.startDate}, 'YYYY-MM-DD')


        AND TO_CHAR(create_time, 'YYYY-MM-DD') <= TO_CHAR(#{query.endDate}, 'YYYY-MM-DD')



    ORDER BY message_id DESC

SELECT count(1)
FROM t_message
where receiver_user_type = #{receiverUserType}
  AND receiver_user_id = #{receiverUserId}
  AND read = false
